import { useEffect, useRef, useMemo } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import type { TweetGroup, Event } from '~/types/bluebird';
import { Box } from 'styled-system/jsx';
import { GroupedTweet } from '~/components/bluebird/GroupedTweet';
import { useToaster } from '~/context/ToasterContext';
import type { CombinedTweetEventsGroups } from '~/hooks/useScrollTracking';
import { useScrollTracking } from '~/hooks/useScrollTracking';
import { EventDisplay } from '~/components/bluebird/EventDisplay';
import { parseUtcString } from '~/utils/date';

interface StaticReadingModeProps {
  lastReadTweetId?: string | null;
  onCurrentMonthYearChange: (monthYear: string | null) => void;
  groupedTweets: TweetGroup[];
  events: Event[];
  useEnglishName?: boolean;
  searchQuery: string;
}

export const LOCAL_STORAGE_KEY = 'bluebirdReadingModeLastReadTweetIdStatic';

export function StaticReadingMode({
  lastReadTweetId,
  onCurrentMonthYearChange,
  groupedTweets,
  events,
  useEnglishName,
  searchQuery
}: StaticReadingModeProps) {
  const parentRef = useRef<HTMLDivElement>(null);
  const { toast } = useToaster();

  const combinedData = useMemo(() => {
    const mappedTweets = groupedTweets.map((item) => ({
      id: item.tweets[0].id,
      type: 'groupedTweet' as const,
      data: item,
      timestamp: parseUtcString(item.group_start_time).getTime()
    }));

    const mappedEvents = events.map((event) => ({
      id: event.id,
      type: 'event' as const,
      data: event,
      timestamp: new Date(event.eventDate).getTime()
    }));

    const allData = [...mappedTweets, ...mappedEvents].sort((a, b) => a.timestamp - b.timestamp);

    if (!searchQuery) {
      return allData as CombinedTweetEventsGroups[];
    }
    const lowerCaseQuery = searchQuery.toLowerCase();
    return allData.filter((item) => {
      if (item.type === 'groupedTweet') {
        return item.data.tweets.some((tweet) => tweet.text.toLowerCase().includes(lowerCaseQuery));
      } else if (item.type === 'event') {
        return item.data.title.toLowerCase().includes(lowerCaseQuery);
      }
      return false;
    }) as CombinedTweetEventsGroups[];
  }, [groupedTweets, events, searchQuery]);

  const virtualizer = useVirtualizer({
    count: combinedData.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 250, // Estimate average item size
    overscan: 5
  });

  const virtualItems = virtualizer.getVirtualItems();

  useEffect(() => {
    if (lastReadTweetId) {
      const index = combinedData.findIndex((item) =>
        item.type === 'groupedTweet'
          ? item.data.tweets.some((t) => t.id === lastReadTweetId)
          : item.id === lastReadTweetId
      );
      if (index !== -1) {
        console.log('SCROLL TO ', lastReadTweetId);
        setTimeout(() => virtualizer.scrollToIndex(index, { align: 'start', behavior: 'auto' }));
      }
    }
  }, [lastReadTweetId]);

  useEffect(() => {
    if (searchQuery && parentRef.current) {
      parentRef.current.scrollTo(0, 0);
    }
  }, [searchQuery]);

  useScrollTracking({
    parentRef,
    virtualizer,
    data: combinedData,
    localStorageKey: LOCAL_STORAGE_KEY,
    onCurrentMonthYearChange
  });

  const onCopy = (text: string, type: 'text' | 'link') => {
    navigator.clipboard.writeText(text).then(
      () => {
        toast?.(`Copied ${type} to clipboard!`);
      },
      (err) => {
        toast?.('Failed to copy!');
        console.error('Could not copy text: ', err);
      }
    );
  };

  return (
    <Box
      ref={parentRef}
      height={{
        base: 'calc(100vh - 64px - 60px)',
        md: 'calc(100vh - 64px)'
      }}
      overflowY="auto"
    >
      <Box style={{ height: `${virtualizer.getTotalSize()}px` }} position="relative">
        {virtualItems.map((virtualItem) => {
          const item = combinedData[virtualItem.index];
          return (
            <Box
              key={virtualItem.key}
              data-index={virtualItem.index}
              ref={virtualizer.measureElement}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                transform: `translateY(${virtualItem.start}px)`
              }}
            >
              {item.type === 'groupedTweet' && (
                <GroupedTweet group={item.data} onCopy={onCopy} useEnglishName={useEnglishName} />
              )}
              {item.type === 'event' && (
                <EventDisplay event={item.data} useEnglish={useEnglishName} />
              )}
            </Box>
          );
        })}
      </Box>
    </Box>
  );
}
