import { FaRegCopy, FaExternalLinkAlt, FaHeart, FaLink, FaEllipsisV } from 'react-icons/fa';
import React from 'react';
import { useTranslation } from 'react-i18next';
import Twemoji from 'react-twemoji';
import { Link } from '../ui/link';
import { Text } from '../ui/text';
import { Button } from '../ui/button';
import { Menu } from '../ui/menu';
import { formatTweetText } from './TweetEntities';
import { Box, Divider, HStack, Stack, styled } from 'styled-system/jsx';
import type { PrunedTweet } from '~/utils/prune-tweets';
import { formatProfilePictureUrl } from '~/utils/image';
import { getCharacterByXAccount } from '~/utils/character-data';
import { css } from 'styled-system/css';

interface TweetProps {
  tweet: PrunedTweet;
  hideBottom?: boolean;
  hideInfo?: boolean;
  showLine?: boolean;
  quoted?: boolean;
  useEnglishName?: boolean;
  onCopy?: (text: string, type: 'text' | 'link') => void;
  children?: React.ReactNode;
}

export function Tweet({
  tweet,
  hideBottom,
  hideInfo,
  showLine,
  quoted,
  useEnglishName,
  onCopy,
  children
}: TweetProps) {
  const { t } = useTranslation();
  const tweetDate = new Date(tweet.createdAt);

  const dateTimeOptions: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  };

  const character = getCharacterByXAccount(tweet.author.userName);

  const PRE_RELEASE_DATE = new Date('2025-05-12T00:00:00Z');
  const isBeforePublic = tweetDate < PRE_RELEASE_DATE;
  const isBeforeJoin =
    character?.joinDate && tweetDate > PRE_RELEASE_DATE && tweetDate < new Date(character.joinDate);

  const profilePicture = isBeforePublic
    ? character?.prePublicData.image
    : formatProfilePictureUrl(tweet.author.profilePicture);

  const baseName = isBeforePublic
    ? character?.prePublicData.name
    : useEnglishName && character
      ? `${character.englishName}@IKIZULIVE!`
      : tweet.author.name;

  const displayName = isBeforeJoin ? baseName?.split('@')[0] : baseName;

  const menu = (
    <Menu.Root>
      <Menu.Trigger asChild>
        <Button
          variant="ghost"
          size="xs"
          title={t('bluebird.tweet.more_options')}
          px="0.5"
          color="fg.subtle"
        >
          <FaEllipsisV size={12} />
        </Button>
      </Menu.Trigger>
      <Menu.Positioner>
        <Menu.Content zIndex="overlay">
          <Menu.ItemGroup>
            <Menu.Item value="copy-text" onClick={() => onCopy?.(tweet.text, 'text')}>
              <HStack gap="2">
                <FaRegCopy /> {t('bluebird.tweet.copy_text')}
              </HStack>
            </Menu.Item>
            <Menu.Item value="open-tweet">
              <Link
                href={tweet.twitterUrl}
                target="_blank"
                rel="noopener noreferrer"
                display="block"
                w="full"
                textDecoration="none"
                _hover={{ textDecoration: 'none !important' }}
              >
                <HStack gap="2">
                  <FaExternalLinkAlt /> {t('bluebird.tweet.open_in_twitter')}
                </HStack>
              </Link>
            </Menu.Item>
            <Menu.Item value="like">
              <HStack gap="2">
                <FaHeart /> {t('bluebird.tweet.like')}
              </HStack>
            </Menu.Item>
            <Menu.Item value="copy-link" onClick={() => onCopy?.(tweet.url, 'link')}>
              <HStack gap="2">
                <FaLink /> {t('bluebird.tweet.copy_link')}
              </HStack>
            </Menu.Item>
          </Menu.ItemGroup>
        </Menu.Content>
      </Menu.Positioner>
    </Menu.Root>
  );
  return (
    <Box
      className="tweet"
      data-tweet-id={tweet.id}
      cursor="pointer"
      display="flex"
      borderBottomWidth={hideBottom ? '0' : '1px'}
      borderColor="border.default"
      px={quoted ? 0 : '4'}
      pt={hideInfo || quoted ? 0 : '4'}
      pb={hideBottom || quoted ? 0 : '4'}
      transitionDuration="200ms"
      transitionProperty="colors"
      _hover={{ bg: 'bg.subtle' }}
    >
      <Box
        display="flex"
        gap="3"
        alignItems="flex-start"
        w="full"
        textDecoration="unset"
        _hover={{ textDecoration: 'unset' }}
      >
        <Stack
          gap="0"
          flexShrink="0"
          alignItems="center"
          w={quoted ? '8' : { base: 10, md: '12' }}
          h="full"
        >
          {!hideInfo && (
            <Box
              borderRadius="full"
              w={quoted ? '8' : { base: 10, md: '12' }}
              h={quoted ? '8' : { base: 10, md: '12' }}
              overflow="hidden"
            >
              <styled.img
                src={profilePicture}
                alt={tweet.author.name}
                transform="scale(1.1)"
                objectFit="cover"
                w={quoted ? '8' : { base: 10, md: '12' }}
                h={quoted ? '8' : { base: 10, md: '12' }}
              />
            </Box>
          )}
          {showLine && (
            <Box
              flex="1"
              borderLeft="3px solid"
              borderLeftColor="border.muted"
              height="full"
              mb={!hideBottom ? '8' : 0}
            ></Box>
          )}
        </Stack>
        <Stack position="relative" gap="0" direction="column" flexGrow="1" minW="0" h="full">
          {!hideInfo && (
            <HStack gap="1" justifyContent="flex-end" alignItems="center" mb="0.5" flexWrap="wrap">
              <HStack flexGrow="1" alignItems="center">
                <Text
                  color="fg.default"
                  textOverflow="ellipsis"
                  textWrap="nowrap"
                  fontSize={quoted ? 'sm' : 'base'}
                  fontWeight="bold"
                  overflow="hidden"
                >
                  {displayName}
                </Text>
                <Text
                  color="fg.muted"
                  textOverflow="ellipsis"
                  textWrap="nowrap"
                  fontSize={quoted ? 'xs' : 'sm'}
                  overflow="hidden"
                >
                  @{tweet.author.userName}
                </Text>
              </HStack>
              <Text color="fg.muted" fontSize={quoted ? 'xs' : 'sm'}>
                {tweetDate.toLocaleString([], dateTimeOptions)}
              </Text>
              {hideBottom && menu}
            </HStack>
          )}
          <HStack
            flex="1"
            gap={0.2}
            alignItems="flex-start"
            w="full"
            h="full"
            mt={hideInfo ? '4' : 0}
          >
            <Text
              flex="1"
              color="fg.default"
              wordBreak="break-word"
              fontSize={quoted ? 'sm' : 'base'}
              whiteSpace="pre-wrap"
            >
              <Twemoji options={{ className: 'twemoji' }}>
                {formatTweetText(tweet.text, tweet.entities)}
              </Twemoji>
            </Text>
            {hideInfo && (
              <Stack gap="0" justifyContent="flex-end" alignItems="center">
                <Text color="fg.muted" fontSize={quoted ? 'xs' : 'sm'}>
                  {tweetDate.toLocaleString([], { hour: '2-digit', minute: '2-digit' })}
                </Text>
                {hideBottom && menu}
              </Stack>
            )}
          </HStack>
          {(tweet.quoted_tweet || tweet.retweeted_tweet) && (
            <Box border="1px solid" borderColor="border.default" rounded="xl" mt="2" p={2}>
              {tweet.retweeted_tweet && (
                <Link
                  href={tweet.retweeted_tweet.twitterUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  display="block"
                  w="full"
                  textDecoration="none"
                  _hover={{ textDecoration: 'none !important' }}
                >
                  <Tweet
                    tweet={tweet.retweeted_tweet}
                    onCopy={onCopy}
                    hideBottom
                    quoted
                    useEnglishName={useEnglishName}
                  />
                </Link>
              )}
              {tweet.quoted_tweet && (
                <Link
                  href={tweet.quoted_tweet.twitterUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  display="block"
                  w="full"
                  textDecoration="none"
                  _hover={{ textDecoration: 'none !important' }}
                >
                  <Tweet
                    tweet={tweet.quoted_tweet}
                    onCopy={onCopy}
                    hideBottom
                    quoted
                    useEnglishName={useEnglishName}
                  />
                </Link>
              )}
            </Box>
          )}
          {children && children}

          {hideBottom && !quoted && <Divider mt="4" borderStyle="dashed" />}
          {!hideBottom && (
            <HStack justifyContent="space-between" h="full" mt="2" color="fg.subtle">
              <HStack
                title={t('bluebird.tweet.copy_text')}
                onClick={(e) => {
                  e.preventDefault();
                  onCopy?.(tweet.text, 'text');
                }}
                cursor="pointer"
                justifyContent="center"
                alignItems="center"
                spaceX="1"
                color="fg.subtle"
              >
                <FaRegCopy className={css({ w: 4, h: 4 })} />
              </HStack>
              <Link
                href={tweet.twitterUrl}
                target="_blank"
                rel="noopener noreferrer"
                title={t('bluebird.tweet.open_in_twitter')}
                color="fg.subtle"
              >
                <HStack cursor="pointer" justifyContent="center" alignItems="center" spaceX="1">
                  <FaExternalLinkAlt className={css({ w: 4, h: 4 })} />
                </HStack>
              </Link>
              <HStack
                title={t('bluebird.tweet.like')}
                cursor="pointer"
                justifyContent="center"
                alignItems="center"
                spaceX="1"
              >
                <FaHeart className={css({ w: 4, h: 4 })} />
              </HStack>
              <HStack
                onClick={(e) => {
                  e.preventDefault();
                  onCopy?.(tweet.url, 'link');
                }}
                title={t('bluebird.tweet.copy_link')}
                cursor="pointer"
                justifyContent="center"
                alignItems="center"
                spaceX="1"
              >
                <FaLink className={css({ w: 4, h: 4 })} />
              </HStack>
              <Box />
            </HStack>
          )}
        </Stack>
      </Box>
    </Box>
  );
}
