import { useEffect } from 'react';
import type { Virtualizer } from '@tanstack/react-virtual';
import { debounce } from '@tanstack/react-virtual';
import { findClosestVirtualItemToTop } from '~/utils/virtualizer';
import type { DBTweet, Event, TweetGroup } from '~/types/bluebird';

export type CombinedTweetEventsGroups = { id: string; timestamp: number } & (
  | { type: 'groupedTweet'; data: TweetGroup }
  | { type: 'tweet'; data: DBTweet }
  | { type: 'event'; data: Event }
);

interface UseScrollTrackingProps {
  parentRef: React.RefObject<HTMLElement | null>;
  virtualizer: Virtualizer<HTMLDivElement, Element>;
  data: CombinedTweetEventsGroups[];
  localStorageKey: string;
  onCurrentMonthYearChange: (monthYear: string | null) => void;
}

export const useScrollTracking = ({
  parentRef,
  virtualizer,
  data,
  localStorageKey,
  onCurrentMonthYearChange
}: UseScrollTrackingProps) => {
  useEffect(() => {
    const scrollElement = parentRef.current;
    if (!scrollElement) return;

    const handleScroll = () => {
      const closestItem = findClosestVirtualItemToTop(scrollElement, virtualizer);
      if (closestItem && data[closestItem.index]) {
        const item = data[closestItem.index];
        let idToSave: string | undefined;

        if (item.type === 'tweet') {
          idToSave = item.id;
        } else if (item.type === 'groupedTweet') {
          idToSave = item.data.tweets[0].id;
        }

        if (idToSave) {
          localStorage.setItem(localStorageKey, idToSave);
        }

        const date = new Date(item.timestamp);
        const monthYear = `${date.getFullYear()}-${(date.getMonth() + 1)
          .toString()
          .padStart(2, '0')}`;
        onCurrentMonthYearChange(monthYear);
      }
    };

    // Set initial progress
    handleScroll();

    const debouncedHandleScroll = debounce(window, handleScroll, 200);
    scrollElement.addEventListener('scroll', debouncedHandleScroll);

    return () => {
      scrollElement.removeEventListener('scroll', debouncedHandleScroll);
    };
  }, [virtualizer, data, onCurrentMonthYearChange, localStorageKey]);
};
